style.css:
@-moz-document domain("roblox.com") {
/* Fundo animado */
  body {
    background: url("https://i.pinimg.com/originals/b9/a7/15/b9a715c3c3ccd918fbd6b75f9e8c92c8.gif") no-repeat center center fixed !important;
    background-size: cover !important;
    color: #000000 !important; /* Cor do texto (preto) */
  }

  /* Cor do texto principal */
  * {
    color: #000000 !important; /* Troque para #b30059 se quiser rosa escuro */
  }

  /* Fundo das seções principais transparente */
  .content, .container, .game-page, .main-content, .rbx-body {
    background: rgba(255, 255, 255, 0.6) !important; /* leve fundo branco translúcido */
    border-radius: 10px !important;
  }

  /* Barra superior (navbar) */
  .navbar, .nav-container, .navigation-container {
    background-color: #ff66b2 !important; /* rosa */
    border-bottom: 2px solid #b30059 !important;
  }

  /* Botões */
  button, .btn, .rbx-btn-primary, .rbx-btn-secondary {
    background-color: #b30059 !important; /* rosa escuro */
    color: #ffffff !important; /* texto branco nos botões */
    border: none !important;
    border-radius: 8px !important;
    transition: all 0.3s ease !important;
  }

  /* Efeito hover nos botões */
  button:hover, .btn:hover, .rbx-btn-primary:hover, .rbx-btn-secondary:hover {
    background-color: #ff99cc !important; /* rosa claro ao passar o mouse */
  }

  /* Barra lateral */
  .left-col, .sidebar, .menu, .menu-item, .side-menu {
    background-color: rgba(255, 204, 229, 0.8) !important;
  }
}
